import json

head = (payload or "").lstrip()
if not head:
    return "empty"
if head[0] not in "[{":
    return "csv"

try:
    document = json.loads(payload)
except ValueError:
    # JSON-looking but not JSON. CSV is the honest fallback: the row reader
    # reports the rows it could not read rather than failing the whole file.
    return "csv"

if isinstance(document, list):
    first = document[0] if document else None
    if isinstance(first, dict) and ("Event" in first or "Attribute" in first):
        return "misp"
    return "stix"

if isinstance(document, dict):
    if document.get("type") == "bundle" or "spec_version" in document:
        return "stix"
    if document.get("type") == "indicator":
        return "stix"
    if "Event" in document or "response" in document or "Attribute" in document:
        return "misp"
    # A MISP feed manifest is a bare object keyed by event uuid.
    for value in document.values():
        if isinstance(value, dict) and "info" in value:
            return "misp"

return "unknown"

out = []
for tag in (holder or {}).get("Tag") or []:
    if isinstance(tag, dict) and tag.get("name"):
        out.append(str(tag["name"]))
    elif isinstance(tag, str) and tag:
        out.append(tag)
return out

for tag in tags or []:
    lowered = str(tag).lower().strip()
    if lowered.startswith("tlp:"):
        return lowered.split(":", 1)[1].strip() or None
return None

from soar.intel.indicators import detect_type

kind = (misp_type or "").strip().lower()
text = (raw or "").strip()
if not kind or not text:
    return []

if "|" in kind:
    left_type, _, right_type = kind.partition("|")
    left_value, _, right_value = text.partition("|")
    return (misp_attribute_values(left_type, left_value)
            + misp_attribute_values(right_type, right_value))

if kind in ("ip-src", "ip-dst", "ip", "ip-host", "dst-ip", "src-ip"):
    detected = detect_type(text)
    return [(detected, text)] if detected in ("ipv4", "ipv6") else []
if kind in ("domain", "hostname", "domain-name"):
    return [("domain", text)]
if kind in ("url", "uri", "link"):
    return [("url", text)]
if kind in ("md5", "sha1", "sha256"):
    return [(kind, text)]
if kind in ("email", "email-src", "email-dst", "email-reply-to",
            "target-email", "whois-registrant-email"):
    return [("email", text)]
if kind == "vulnerability":
    return [("cve", text)]

# Context, not detection: a filename or a comment is worth reading on the
# event and worth nothing as a standalone indicator.
if kind in ("filename", "text", "comment", "other", "datetime", "port",
            "size-in-bytes", "attachment", "malware-sample", "counter",
            "first-seen", "last-seen", "threat-actor", "campaign-name"):
    return []

# Anything else: let the classifier decide, and drop what it cannot place.
detected = detect_type(text)
return [(detected, text)] if detected != "unknown" else []

import json

try:
    document = json.loads(payload)
except ValueError as error:
    return {"indicators": [], "follow": [], "rejected": 0,
            "errors": ["not valid JSON: %s" % error]}

events = []
follow = []
errors = []

if isinstance(document, list):
    events = [entry.get("Event", entry) for entry in document
              if isinstance(entry, dict)]
elif isinstance(document, dict) and "Event" in document:
    events = [document["Event"]]
elif isinstance(document, dict) and isinstance(document.get("response"), list):
    events = [entry.get("Event", entry) for entry in document["response"]
              if isinstance(entry, dict)]
elif isinstance(document, dict) and isinstance(document.get("response"), dict):
    # /attributes/restSearch answers with attributes and no event around them.
    events = [{"Attribute": document["response"].get("Attribute") or []}]
elif isinstance(document, dict) and isinstance(document.get("Attribute"), list):
    events = [{"Attribute": document["Attribute"]}]
elif isinstance(document, dict):
    for uuid, summary in document.items():
        if isinstance(summary, dict) and "info" in summary:
            follow.append("%s.json" % uuid)
    if not follow:
        errors.append("JSON with no MISP event, attribute list or manifest in it")
    return {"indicators": [], "follow": follow, "rejected": 0, "errors": errors}

# to_ids is MISP's own statement that an attribute is fit for detection.
# Ingesting the rest turns a feed into a false-positive generator, so taking
# everything is opt-in rather than the default.
strict = defaults.get("trusted_only", True)

indicators = []
rejected = 0
seen = set()

for event in events:
    if not isinstance(event, dict):
        continue
    event_tags = misp_document_tags(event)
    attributes = list(event.get("Attribute") or [])
    for grouped in event.get("Object") or []:
        if isinstance(grouped, dict):
            attributes.extend(grouped.get("Attribute") or [])

    for attribute in attributes:
        if not isinstance(attribute, dict):
            continue
        if strict and not attribute.get("to_ids"):
            rejected += 1
            continue
        pairs = misp_attribute_values(attribute.get("type", ""),
                                      attribute.get("value", ""))
        if not pairs:
            rejected += 1
            continue

        tags = event_tags + misp_document_tags(attribute)
        for kind, value in pairs:
            record = feed_indicator(kind, value, defaults, {
                "tags": tags,
                "tlp": misp_tlp_tag(tags),
                "comment": attribute.get("comment") or event.get("info"),
                "source_ref": attribute.get("uuid") or event.get("uuid"),
            })
            key = (record["type"], record["normalised"])
            if key in seen:
                continue
            seen.add(key)
            indicators.append(record)

return {"indicators": indicators, "follow": follow, "rejected": rejected,
        "errors": errors}

lowered = (path or "").lower().replace("'", "").replace('"', "")

if lowered.startswith("ipv4-addr:"):
    return "ipv4"
if lowered.startswith("ipv6-addr:"):
    return "ipv6"
if lowered.startswith("domain-name:"):
    return "domain"
if lowered.startswith("url:"):
    return "url"
if lowered.startswith("email-addr:"):
    return "email"
if lowered.startswith("vulnerability:"):
    return "cve"
if lowered.startswith("file:hashes."):
    algorithm = lowered.split("file:hashes.", 1)[1]
    algorithm = "".join(c for c in algorithm if c.isalnum())
    return {"sha256": "sha256", "sha1": "sha1", "md5": "md5"}.get(algorithm)
return None

markings = {}
for entry in objects or []:
    if not isinstance(entry, dict) or entry.get("type") != "marking-definition":
        continue
    definition = entry.get("definition") or {}
    label = definition.get("tlp") or entry.get("name")
    if label:
        markings[entry.get("id")] = str(label).lower().replace("tlp:", "").strip()

indicators = []
errors = []
rejected = 0
seen = set()

for entry in objects or []:
    if not isinstance(entry, dict) or entry.get("type") != "indicator":
        continue
    if entry.get("revoked"):
        rejected += 1
        continue

    pattern_type = str(entry.get("pattern_type") or "stix").lower()
    if pattern_type != "stix":
        # A YARA or Snort rule is a detection, not an observable. There is no
        # honest way to store one in an indicator table.
        rejected += 1
        if len(errors) < 20:
            errors.append("%s: %s patterns are rules, not observables"
                          % (entry.get("id"), pattern_type))
        continue

    pairs = stix_pattern_values(entry.get("pattern", ""))
    if not pairs:
        rejected += 1
        continue

    tlp = None
    for reference in entry.get("object_marking_refs") or []:
        tlp = markings.get(reference) or tlp

    confidence = entry.get("confidence")
    for kind, value in pairs:
        record = feed_indicator(kind, value, defaults, {
            "tags": [str(label) for label in (entry.get("labels") or [])],
            "tlp": tlp,
            "confidence": confidence,
            "expires_at": entry.get("valid_until"),
            "source_ref": entry.get("id"),
            "comment": entry.get("name") or entry.get("description"),
        })
        key = (record["type"], record["normalised"])
        if key in seen:
            continue
        seen.add(key)
        indicators.append(record)

return {"indicators": indicators, "follow": [], "rejected": rejected,
        "errors": errors}

