from soar.intel.indicators import detect_type, refang

generic = ("value", "indicator", "ioc", "observable", "artifact")

# Name to the type it implies; "" means let the classifier decide, which is
# what "ip" and "hash" need since they do not say v4/v6 or which digest.
typed = [("url", "url"), ("uri", "url"), ("domain", "domain"),
         ("hostname", "domain"), ("host", "domain"),
         ("ip", ""), ("ip_address", ""), ("dst_ip", ""), ("src_ip", ""),
         ("ipv4", "ipv4"), ("ipv6", "ipv6"),
         ("sha256", "sha256"), ("sha256_hash", "sha256"),
         ("sha1", "sha1"), ("sha1_hash", "sha1"),
         ("md5", "md5"), ("md5_hash", "md5"), ("hash", ""),
         ("email", "email"), ("cve", "cve")]

for name in generic:
    if name in header:
        return {"index": header.index(name), "hint": ""}
for name, hint in typed:
    if name in header:
        return {"index": header.index(name), "hint": hint}

sample = rows[:50]
if not sample:
    return {"index": -1, "hint": ""}
width = max(len(row) for row in sample)
supported = ("ipv4", "ipv6", "domain", "url", "email", "md5", "sha1",
             "sha256", "cve")

best_index = -1
best_hits = 0
for index in range(width):
    hits = 0
    for row in sample:
        if index >= len(row):
            continue
        if detect_type(refang(row[index].strip().strip(chr(34)).strip())) in supported:
            hits += 1
    if hits > best_hits:
        best_index = index
        best_hits = hits

# Half the sampled rows, so a column that merely happens to contain one
# address somewhere is not mistaken for the indicator column.
if best_hits * 2 >= len(sample):
    return {"index": best_index, "hint": ""}
return {"index": -1, "hint": ""}

from soar.intel.indicators import detect_type, refang

import csv

supported = ("ipv4", "ipv6", "domain", "url", "email", "md5", "sha1",
             "sha256", "cve")
meta = ("type", "indicator_type", "confidence", "tlp", "tags",
        "description", "comment", "expiration", "expires_at", "valid_until")

comments = []
lines = []
for line in (payload or "").splitlines():
    stripped = line.strip()
    if not stripped:
        continue
    if stripped.startswith(("#", ";", "//")):
        comments.append(stripped.lstrip("#;/ ").strip())
        continue
    lines.append(line)

if not lines:
    return {"indicators": [], "follow": [], "rejected": 0,
            "errors": ["the document has no data rows, only comments"]}

try:
    delimiter = csv.Sniffer().sniff("\n".join(lines[:20]),
                                    delimiters=",;\t|").delimiter
except csv.Error:
    delimiter = ","

rows = [row for row in csv.reader(lines, delimiter=delimiter) if row]
if not rows:
    return {"indicators": [], "follow": [], "rejected": 0, "errors": []}

def looks_like_header(cells):
    for cell in cells:
        if cell in meta:
            return True
        if csv_value_column([cell], [])["index"] == 0:
            return True
    return False

header = []
first = [cell.strip().strip('"').lower() for cell in rows[0]]
if looks_like_header(first):
    header = first
    rows = rows[1:]
else:
    # The commented-header convention, recovered from the last comment line
    # whose shape matches the data.
    for candidate in reversed(comments):
        cells = [cell.strip().strip('"').lower()
                 for cell in candidate.split(delimiter)]
        if len(cells) == len(rows[0]) and looks_like_header(cells):
            header = cells
            break

located = csv_value_column(header, rows)
value_index = located["index"]
hint = located["hint"]
if value_index < 0:
    return {"indicators": [], "follow": [], "rejected": len(rows),
            "errors": ["no column in this document looks like an indicator; "
                       "columns seen: %s" % (", ".join(header) or "none named")]}

def cell(text):
    return text.strip().strip(chr(34)).strip()

def column(row, *names):
    for name in names:
        if name in header:
            index = header.index(name)
            if index < len(row):
                return cell(row[index])
    return ""

indicators = []
rejected = 0
seen = set()

for row in rows:
    if value_index >= len(row):
        rejected += 1
        continue
    raw = cell(row[value_index])
    if not raw:
        rejected += 1
        continue

    kind = column(row, "type", "indicator_type").lower() or hint
    if kind not in supported:
        kind = detect_type(refang(raw))
    if kind not in supported:
        rejected += 1
        continue

    confidence = column(row, "confidence")
    tags = [tag.strip()
            for tag in column(row, "tags").replace(";", ",").split(",")
            if tag.strip()]
    record = feed_indicator(kind, raw, defaults, {
        "tags": tags,
        "tlp": column(row, "tlp") or None,
        "confidence": int(confidence) if confidence.isdigit() else None,
        "expires_at": column(row, "expiration", "expires_at", "valid_until"),
        "comment": column(row, "description", "comment") or None,
    })
    key = (record["type"], record["normalised"])
    if key in seen:
        continue
    seen.add(key)
    indicators.append(record)

return {"indicators": indicators, "follow": [], "rejected": rejected,
        "errors": []}

chosen = (feed_format or "auto").strip().lower()
if chosen in ("", "auto", "detect"):
    chosen = sniff_feed_format(payload)

if chosen in ("misp", "misp-json", "misp_json"):
    parsed = parse_misp_feed(payload, defaults or {})
elif chosen in ("stix", "stix2", "stix2.1", "taxii", "bundle"):
    parsed = parse_stix_feed(payload, defaults or {})
elif chosen in ("csv", "txt", "text", "plain", "list", "blocklist"):
    parsed = parse_csv_feed(payload, defaults or {})
elif chosen == "empty":
    parsed = {"indicators": [], "follow": [], "rejected": 0,
              "errors": ["the feed returned an empty document"]}
else:
    parsed = {"indicators": [], "follow": [], "rejected": 0,
              "errors": ["unsupported feed format %r" % chosen]}

parsed["format"] = chosen
return parsed
